script:
frappe.ui.form.on('Sales Order', {
    custom_consignee_(frm) {
        erpnext_xinyu_render_address(frm, 'custom_consignee_', 'custom_consignee_detail');
    },
    custom_notify_party(frm) {
        erpnext_xinyu_render_address(frm, 'custom_notify_party', 'custom_notify_party_detail');
    }
})

function erpnext_xinyu_render_address(frm, address_field, display_field) {
    if (!frm.doc[address_field]) {
        frm.set_value(display_field, '');
        return;
    }
    frappe.call({
        method: 'frappe.contacts.doctype.address.address.get_address_display',
        args: { address_dict: frm.doc[address_field] },
        callback: function (r) {
            let html = (r.message || '')
                .replace(/\s*<br\s*\/?>\s*/gi, '<br>')
                .replace(/(?:<br>){2,}/gi, '<br>')
                .replace(/^(?:<br>)+|(?:<br>)+$/gi, '');
            frm.set_value(display_field, html);
        }
    });
}

frappe.provide('erpnext_xinyu');
erpnext_xinyu.CALC_PRECISION = erpnext_xinyu.CALC_PRECISION || 2;

frappe.ui.form.on('Sales Order Item', {
    custom_customs_rate(frm, cdt, cdn) { erpnext_xinyu_calc_row(frm, cdt, cdn); },
    custom_commission_rate(frm, cdt, cdn) { erpnext_xinyu_calc_row(frm, cdt, cdn); },
    custom_factory_rate(frm, cdt, cdn) { erpnext_xinyu_calc_row(frm, cdt, cdn); },
    qty(frm, cdt, cdn) { erpnext_xinyu_calc_row(frm, cdt, cdn); },
    item_code(frm, cdt, cdn) { erpnext_xinyu_calc_row(frm, cdt, cdn); },
    items_remove(frm) { erpnext_xinyu_calc_total(frm); }
});

frappe.ui.form.on('Sales Order', {
    conversion_rate(frm) { erpnext_xinyu_calc_all(frm); }
});

function erpnext_xinyu_calc_all(frm) {
    const rows = frm.doc.items || [];
    if (!rows.length) {
        erpnext_xinyu_calc_total(frm);
        return;
    }

    const promises = rows.map(function (row) {
        return erpnext_xinyu_calc_row(frm, row.doctype, row.name, true);
    });

    Promise.all(promises).then(function () {
        erpnext_xinyu_calc_total(frm);
    });
}

function erpnext_xinyu_calc_row(frm, cdt, cdn, skip_total) {
    const row = locals[cdt][cdn];
    if (!row) return Promise.resolve();

    const conversion_rate = flt(frm.doc.conversion_rate, erpnext_xinyu.CALC_PRECISION) || 1;
    const customs_rate = flt(row.custom_customs_rate, erpnext_xinyu.CALC_PRECISION);
    const commission_rate = flt(row.custom_commission_rate, erpnext_xinyu.CALC_PRECISION);
    const factory_rate = flt(row.custom_factory_rate, erpnext_xinyu.CALC_PRECISION);
    const qty = flt(row.qty);

    function finish(rebate_rate) {
        rebate_rate = flt(rebate_rate, 0);

        const excl_commission_rate = flt(
            customs_rate - commission_rate,
            erpnext_xinyu.CALC_PRECISION
        );
        const excl_commission_amount = flt(
            excl_commission_rate * qty,
            erpnext_xinyu.CALC_PRECISION
        );
        const customs_amount = flt(
            customs_rate * qty,
            erpnext_xinyu.CALC_PRECISION
        );
        const commission_amount = flt(
            commission_rate * qty,
            erpnext_xinyu.CALC_PRECISION
        );
        const vat = flt(factory_rate * 0.9, erpnext_xinyu.CALC_PRECISION);
        const tax = flt(
            vat / 1.13 * (rebate_rate / 100),
            erpnext_xinyu.CALC_PRECISION
        );
        const exw = flt(
            conversion_rate ? (factory_rate - tax) / conversion_rate : 0,
            erpnext_xinyu.CALC_PRECISION
        );
        const insurance = flt(exw * 1.1 * 0.001, erpnext_xinyu.CALC_PRECISION);
        const quote = flt(exw + insurance, erpnext_xinyu.CALC_PRECISION);
        const quote_with_credit_term = flt(
            quote * 1.006,
            erpnext_xinyu.CALC_PRECISION
        );
        const approved_amount = flt(
            quote_with_credit_term * qty,
            erpnext_xinyu.CALC_PRECISION
        );
        const difference = flt(
            excl_commission_amount - approved_amount,
            erpnext_xinyu.CALC_PRECISION
        );

        erpnext_xinyu_set_row_value(cdt, cdn, row, 'custom_customs_excl_commission_rate', excl_commission_rate);
        erpnext_xinyu_set_row_value(cdt, cdn, row, 'custom_customs_excl_commission_amount', excl_commission_amount);
        erpnext_xinyu_set_row_value(cdt, cdn, row, 'custom_customs_amount', customs_amount);
        erpnext_xinyu_set_row_value(cdt, cdn, row, 'custom_commission_amount', commission_amount);
        erpnext_xinyu_set_row_value(cdt, cdn, row, 'custom_vat', vat);
        erpnext_xinyu_set_row_value(cdt, cdn, row, 'custom_tax', tax);
        erpnext_xinyu_set_row_value(cdt, cdn, row, 'custom_exw', exw);
        erpnext_xinyu_set_row_value(cdt, cdn, row, 'custom_insurance', insurance);
        erpnext_xinyu_set_row_value(cdt, cdn, row, 'custom_quote', quote);
        erpnext_xinyu_set_row_value(cdt, cdn, row, 'custom_quote_with_credit_term', quote_with_credit_term);
        erpnext_xinyu_set_row_value(cdt, cdn, row, 'custom_approved_amount', approved_amount);
        erpnext_xinyu_set_row_value(cdt, cdn, row, 'custom_difference', difference);

        if (!skip_total) erpnext_xinyu_calc_total(frm);
    }

    if (row.item_code) {
        return frappe.db.get_value('Item', row.item_code, 'custom_tax_rebate_rate').then(function (r) {
            finish(r && r.message ? r.message.custom_tax_rebate_rate : 0);
        });
    }

    finish(0);
    return Promise.resolve();
}

function erpnext_xinyu_set_row_value(cdt, cdn, row, fieldname, value) {
    const rounded = flt(value, erpnext_xinyu.CALC_PRECISION);
    if (flt(locals[cdt][cdn][fieldname]) !== rounded) {
        frappe.model.set_value(cdt, cdn, fieldname, rounded);
    }
}

function erpnext_xinyu_calc_total(frm) {
    let total = 0;
    (frm.doc.items || []).forEach(function (row) {
        total += flt(row.custom_difference);
    });
    total = flt(total, erpnext_xinyu.CALC_PRECISION);
    if (flt(frm.doc.custom_total_difference) !== total) {
        frm.set_value('custom_total_difference', total);
    }
    frm.$wrapper.trigger('xinyu_pricing_updated');
}

frappe.provide('erpnext_xinyu');
erpnext_xinyu.CALC_PRECISION = erpnext_xinyu.CALC_PRECISION || 2;

frappe.ui.form.on('Sales Order', {
    setup(frm) {
        const df = frappe.meta.get_docfield('Sales Order', 'custom_evaluation_result');
        if (df) {
            df.formatter = function (value, df) {
                if (!value) {
                    return '';
                }
                let color = 'gray';
                if (value === 'er_success') {
                    color = 'green';
                } else if (value === 'er_fail') {
                    color = 'red';
                }
                return `<span class="indicator ${color}">${__(value, null, df.parent)}</span>`;
            };
        }
        frm.$wrapper.on('xinyu_pricing_updated', function () {
            erpnext_xinyu_calc_shipping_evaluation(frm);
        });
    },
    custom_shipping_fee_domestic(frm) {
        erpnext_xinyu_calc_shipping_evaluation(frm);
    },
    custom_shipping_fee_oversea(frm) {
        erpnext_xinyu_calc_shipping_evaluation(frm);
    }
});

function erpnext_xinyu_calc_shipping_evaluation(frm) {
    const conversion_rate = flt(frm.doc.conversion_rate, erpnext_xinyu.CALC_PRECISION) || 1;
    const domestic = flt(frm.doc.custom_shipping_fee_domestic, erpnext_xinyu.CALC_PRECISION);
    const oversea = flt(frm.doc.custom_shipping_fee_oversea, erpnext_xinyu.CALC_PRECISION);
    const domestic_in_order_currency = flt(
        conversion_rate ? domestic / conversion_rate : 0,
        erpnext_xinyu.CALC_PRECISION
    );
    const shipping_total = flt(
        oversea + domestic_in_order_currency,
        erpnext_xinyu.CALC_PRECISION
    );
    const total_diff = flt(frm.doc.custom_total_difference, erpnext_xinyu.CALC_PRECISION);
    const result = total_diff >= shipping_total ? 'er_success' : 'er_fail';

    if (flt(frm.doc.custom_shipping_fee_total) !== shipping_total) {
        frm.set_value('custom_shipping_fee_total', shipping_total);
    }
    if (frm.doc.custom_evaluation_result !== result) {
        frm.set_value('custom_evaluation_result', result);
        frm.refresh_field('custom_evaluation_result');
    }
}

frappe.ui.form.on('Sales Order Item', {
    custom_unit_package_weight(frm, cdt, cdn) {
        erpnext_xinyu_calc_packaging_row(frm, cdt, cdn);
    },
    qty(frm, cdt, cdn) {
        erpnext_xinyu_calc_packaging_row(frm, cdt, cdn);
    },
    items_remove(frm) {
        erpnext_xinyu_calc_packaging_total(frm);
    }
});

function erpnext_xinyu_calc_packaging_row(frm, cdt, cdn, skip_total) {
    const row = locals[cdt][cdn];
    if (!row) {
        return;
    }

    const qty = flt(row.qty);
    const weight = flt(row.custom_unit_package_weight);
    const package_count = weight > 0 ? Math.ceil(qty / weight) : 0;

    erpnext_xinyu_set_packaging_row_value(cdt, cdn, 'custom_package_count', package_count);

    if (!skip_total) {
        erpnext_xinyu_calc_packaging_total(frm);
    }
}

function erpnext_xinyu_set_packaging_row_value(cdt, cdn, fieldname, value) {
    const rounded = cint(value);
    if (cint(locals[cdt][cdn][fieldname]) !== rounded) {
        frappe.model.set_value(cdt, cdn, fieldname, rounded);
    }
}

function erpnext_xinyu_calc_packaging_total(frm) {
    let total = 0;
    (frm.doc.items || []).forEach(function (row) {
        total += cint(row.custom_package_count);
    });
    total = cint(total);
    if (cint(frm.doc.custom_total_package_count) !== total) {
        frm.set_value('custom_total_package_count', total);
    }
}
